    insert into auth.users (
    insert into auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  insert into public.profiles (id, display_name, avatar_emoji)
    insert into public.quizzes (owner_id, title, description, cover_emoji, status)
  insert into public.questions
    (quiz_id, position, prompt, options, correct_option_id, time_limit_ms, points_base, explanation)
  values
    (v_quiz_id, 1, 'Which planet is closest to the Sun?', '[{"id": "a", "text": "Mercury"}, {"id": "b", "text": "Venus"}, {"id": "c", "text": "Earth"}, {"id": "d", "text": "Mars"}]'::jsonb, 'a', 15000, 1000, 'Mercury orbits at roughly 58 million km from the Sun, closer than any other planet.'),
    (v_quiz_id, 2, 'How many players from one team are on the field during a football match?', '[{"id": "a", "text": "10"}, {"id": "b", "text": "11"}, {"id": "c", "text": "9"}, {"id": "d", "text": "12"}]'::jsonb, 'b', 15000, 1000, 'Each side fields eleven players, one of whom is the goalkeeper.'),
    (v_quiz_id, 3, 'Which is the largest ocean on Earth?', '[{"id": "a", "text": "Atlantic Ocean"}, {"id": "b", "text": "Indian Ocean"}, {"id": "c", "text": "Pacific Ocean"}, {"id": "d", "text": "Arctic Ocean"}]'::jsonb, 'c', 15000, 1000, 'The Pacific covers about a third of the planet''s surface, more than all the land put together.'),
    (v_quiz_id, 4, 'What is the capital of Australia?', '[{"id": "a", "text": "Sydney"}, {"id": "b", "text": "Melbourne"}, {"id": "c", "text": "Perth"}, {"id": "d", "text": "Canberra"}]'::jsonb, 'd', 20000, 1000, 'Canberra was purpose-built as a compromise capital between Sydney and Melbourne.'),
    (v_quiz_id, 5, 'What is the chemical symbol for gold?', '[{"id": "a", "text": "Au"}, {"id": "b", "text": "Ag"}, {"id": "c", "text": "Gd"}, {"id": "d", "text": "Go"}]'::jsonb, 'a', 15000, 1000, 'Au comes from aurum, the Latin word for gold; Ag is silver.'),
    (v_quiz_id, 6, 'Which gas do plants take in during photosynthesis?', '[{"id": "a", "text": "Oxygen"}, {"id": "b", "text": "Carbon dioxide"}, {"id": "c", "text": "Nitrogen"}, {"id": "d", "text": "Hydrogen"}]'::jsonb, 'b', 15000, 1000, 'Plants combine carbon dioxide and water using light energy, and release oxygen.'),
    (v_quiz_id, 7, 'In which country is the Taj Mahal?', '[{"id": "a", "text": "Pakistan"}, {"id": "b", "text": "Bangladesh"}, {"id": "c", "text": "India"}, {"id": "d", "text": "Nepal"}]'::jsonb, 'c', 15000, 1000, 'It stands in Agra, Uttar Pradesh, on the bank of the Yamuna.'),
    (v_quiz_id, 8, 'How many minutes long is a standard football match, excluding stoppage time?', '[{"id": "a", "text": "80"}, {"id": "b", "text": "100"}, {"id": "c", "text": "60"}, {"id": "d", "text": "90"}]'::jsonb, 'd', 15000, 1000, 'Two halves of 45 minutes each, with added time for stoppages.'),
    (v_quiz_id, 9, 'Which is the largest living land animal?', '[{"id": "a", "text": "African elephant"}, {"id": "b", "text": "Giraffe"}, {"id": "c", "text": "Hippopotamus"}, {"id": "d", "text": "White rhinoceros"}]'::jsonb, 'a', 15000, 1000, 'A large bull African elephant can weigh over six tonnes.'),
    (v_quiz_id, 10, 'What does “www” stand for in a web address?', '[{"id": "a", "text": "World Web Wide"}, {"id": "b", "text": "World Wide Web"}, {"id": "c", "text": "Wide World Web"}, {"id": "d", "text": "Web World Wide"}]'::jsonb, 'b', 20000, 1000, 'Tim Berners-Lee named his hypertext system the World Wide Web in 1989.'),
    (v_quiz_id, 11, 'Which Indian city is called the “Silicon Valley of India”?', '[{"id": "a", "text": "Hyderabad"}, {"id": "b", "text": "Pune"}, {"id": "c", "text": "Bengaluru"}, {"id": "d", "text": "Chennai"}]'::jsonb, 'c', 20000, 1000, 'Bengaluru''s concentration of software firms earned it the nickname.'),
    (v_quiz_id, 12, 'How many days are there in a leap year?', '[{"id": "a", "text": "365"}, {"id": "b", "text": "364"}, {"id": "c", "text": "367"}, {"id": "d", "text": "366"}]'::jsonb, 'd', 15000, 1000, 'The extra day, 29 February, keeps the calendar aligned with Earth''s orbit.'),
    (v_quiz_id, 13, 'Which colour appears at the top of a rainbow?', '[{"id": "a", "text": "Red"}, {"id": "b", "text": "Violet"}, {"id": "c", "text": "Green"}, {"id": "d", "text": "Blue"}]'::jsonb, 'a', 15000, 1000, 'Red has the longest wavelength, so it bends least and sits on the outer edge.'),
    (v_quiz_id, 14, 'What is the currency of Japan?', '[{"id": "a", "text": "Won"}, {"id": "b", "text": "Yen"}, {"id": "c", "text": "Yuan"}, {"id": "d", "text": "Ringgit"}]'::jsonb, 'b', 15000, 1000, 'The yen is Japan''s currency; the won is Korean and the ringgit Malaysian.'),
    (v_quiz_id, 15, 'Which vitamin does the body make when skin is exposed to sunlight?', '[{"id": "a", "text": "Vitamin C"}, {"id": "b", "text": "Vitamin A"}, {"id": "c", "text": "Vitamin D"}, {"id": "d", "text": "Vitamin B12"}]'::jsonb, 'c', 15000, 1000, 'Ultraviolet light triggers vitamin D synthesis in the skin.'),
    (v_quiz_id, 16, 'Which river runs through the Grand Canyon?', '[{"id": "a", "text": "Rio Grande"}, {"id": "b", "text": "Columbia River"}, {"id": "c", "text": "Snake River"}, {"id": "d", "text": "Colorado River"}]'::jsonb, 'd', 20000, 1000, 'The Colorado has been cutting the canyon in Arizona for about six million years.'),
    (v_quiz_id, 17, 'Who wrote “On the Origin of Species”?', '[{"id": "a", "text": "Charles Darwin"}, {"id": "b", "text": "Carl Linnaeus"}, {"id": "c", "text": "Louis Pasteur"}, {"id": "d", "text": "Gregor Mendel"}]'::jsonb, 'a', 20000, 1000, 'Darwin published it in 1859, setting out evolution by natural selection.'),
    (v_quiz_id, 18, 'Which element has atomic number 26?', '[{"id": "a", "text": "Copper"}, {"id": "b", "text": "Iron"}, {"id": "c", "text": "Zinc"}, {"id": "d", "text": "Nickel"}]'::jsonb, 'b', 20000, 1000, 'Iron sits at 26 on the periodic table, between manganese and cobalt.'),
    (v_quiz_id, 19, 'The Great Barrier Reef lies off the coast of which country?', '[{"id": "a", "text": "Indonesia"}, {"id": "b", "text": "Philippines"}, {"id": "c", "text": "Australia"}, {"id": "d", "text": "Papua New Guinea"}]'::jsonb, 'c', 20000, 1000, 'It stretches more than 2,300 km along the Queensland coast.'),
    (v_quiz_id, 20, 'Which Indian state has the longest coastline?', '[{"id": "a", "text": "Tamil Nadu"}, {"id": "b", "text": "Andhra Pradesh"}, {"id": "c", "text": "Maharashtra"}, {"id": "d", "text": "Gujarat"}]'::jsonb, 'd', 25000, 1000, 'Gujarat''s coastline runs about 1,600 km along the Arabian Sea.'),
    (v_quiz_id, 21, 'How many balls are bowled in a standard over in cricket?', '[{"id": "a", "text": "Six"}, {"id": "b", "text": "Five"}, {"id": "c", "text": "Four"}, {"id": "d", "text": "Eight"}]'::jsonb, 'a', 15000, 1000, 'An over is six legal deliveries; wides and no-balls do not count.'),
    (v_quiz_id, 22, 'Who was the first woman to win a Nobel Prize?', '[{"id": "a", "text": "Rosalind Franklin"}, {"id": "b", "text": "Marie Curie"}, {"id": "c", "text": "Ada Lovelace"}, {"id": "d", "text": "Dorothy Hodgkin"}]'::jsonb, 'b', 25000, 1000, 'Marie Curie shared the 1903 physics prize and later won chemistry in 1911.'),
    (v_quiz_id, 23, 'Which planet is home to the Great Red Spot?', '[{"id": "a", "text": "Saturn"}, {"id": "b", "text": "Neptune"}, {"id": "c", "text": "Jupiter"}, {"id": "d", "text": "Mars"}]'::jsonb, 'c', 20000, 1000, 'It is a storm wider than Earth that has been observed for centuries.'),
    (v_quiz_id, 24, 'Which is the hardest naturally occurring mineral?', '[{"id": "a", "text": "Quartz"}, {"id": "b", "text": "Corundum"}, {"id": "c", "text": "Topaz"}, {"id": "d", "text": "Diamond"}]'::jsonb, 'd', 20000, 1000, 'Diamond scores a perfect 10 on the Mohs hardness scale.'),
    (v_quiz_id, 25, 'Which country gave the Statue of Liberty to the United States?', '[{"id": "a", "text": "France"}, {"id": "b", "text": "United Kingdom"}, {"id": "c", "text": "Spain"}, {"id": "d", "text": "Netherlands"}]'::jsonb, 'a', 20000, 1000, 'France presented it in 1886 to mark the centenary of American independence.'),
    (v_quiz_id, 26, 'Which is the largest hot desert in the world?', '[{"id": "a", "text": "Gobi"}, {"id": "b", "text": "Sahara"}, {"id": "c", "text": "Kalahari"}, {"id": "d", "text": "Arabian"}]'::jsonb, 'b', 20000, 1000, 'The Sahara covers roughly 9 million square kilometres of North Africa.'),
    (v_quiz_id, 27, 'Which organ produces insulin?', '[{"id": "a", "text": "Liver"}, {"id": "b", "text": "Kidney"}, {"id": "c", "text": "Pancreas"}, {"id": "d", "text": "Spleen"}]'::jsonb, 'c', 20000, 1000, 'Beta cells in the pancreas release insulin to regulate blood sugar.'),
    (v_quiz_id, 28, 'In which year did India become independent?', '[{"id": "a", "text": "1946"}, {"id": "b", "text": "1948"}, {"id": "c", "text": "1950"}, {"id": "d", "text": "1947"}]'::jsonb, 'd', 15000, 1000, 'India became independent on 15 August 1947; the republic followed in 1950.'),
    (v_quiz_id, 29, 'Which language has the most native speakers in the world?', '[{"id": "a", "text": "Mandarin Chinese"}, {"id": "b", "text": "Spanish"}, {"id": "c", "text": "English"}, {"id": "d", "text": "Hindi"}]'::jsonb, 'a', 20000, 1000, 'Mandarin has close to a billion native speakers, ahead of Spanish.'),
    (v_quiz_id, 30, 'What is the chemical formula for table salt?', '[{"id": "a", "text": "KCl"}, {"id": "b", "text": "NaCl"}, {"id": "c", "text": "NaHCO3"}, {"id": "d", "text": "CaCO3"}]'::jsonb, 'b', 20000, 1000, 'Sodium chloride, NaCl, is the compound in everyday table salt.'),
    (v_quiz_id, 31, 'Which ocean trench contains the deepest known point on Earth?', '[{"id": "a", "text": "Tonga Trench"}, {"id": "b", "text": "Java Trench"}, {"id": "c", "text": "Mariana Trench"}, {"id": "d", "text": "Puerto Rico Trench"}]'::jsonb, 'c', 25000, 1000, 'The Challenger Deep in the Mariana Trench lies almost 11 km below the surface.'),
    (v_quiz_id, 32, 'Mount Kilimanjaro is in which country?', '[{"id": "a", "text": "Kenya"}, {"id": "b", "text": "Uganda"}, {"id": "c", "text": "Ethiopia"}, {"id": "d", "text": "Tanzania"}]'::jsonb, 'd', 20000, 1000, 'Kilimanjaro rises in northern Tanzania near the Kenyan border.'),
    (v_quiz_id, 33, 'Who set out the three laws of motion?', '[{"id": "a", "text": "Isaac Newton"}, {"id": "b", "text": "Galileo Galilei"}, {"id": "c", "text": "Johannes Kepler"}, {"id": "d", "text": "Albert Einstein"}]'::jsonb, 'a', 20000, 1000, 'Newton published the laws in Principia Mathematica in 1687.'),
    (v_quiz_id, 34, 'What does DNA stand for?', '[{"id": "a", "text": "Dinucleic acid"}, {"id": "b", "text": "Deoxyribonucleic acid"}, {"id": "c", "text": "Deoxyribose nucleotide"}, {"id": "d", "text": "Diribonucleic acid"}]'::jsonb, 'b', 25000, 1000, 'The name describes the sugar deoxyribose and the acid backbone of the molecule.'),
    (v_quiz_id, 35, 'Which is the largest Indian state by area?', '[{"id": "a", "text": "Madhya Pradesh"}, {"id": "b", "text": "Maharashtra"}, {"id": "c", "text": "Rajasthan"}, {"id": "d", "text": "Uttar Pradesh"}]'::jsonb, 'c', 20000, 1000, 'Rajasthan covers about 342,000 square kilometres, the most of any state.'),
    (v_quiz_id, 36, 'Who painted the Mona Lisa?', '[{"id": "a", "text": "Michelangelo"}, {"id": "b", "text": "Raphael"}, {"id": "c", "text": "Titian"}, {"id": "d", "text": "Leonardo da Vinci"}]'::jsonb, 'd', 15000, 1000, 'Leonardo painted it in Florence in the early sixteenth century.'),
    (v_quiz_id, 37, 'What is the smallest prime number?', '[{"id": "a", "text": "2"}, {"id": "b", "text": "1"}, {"id": "c", "text": "3"}, {"id": "d", "text": "0"}]'::jsonb, 'a', 20000, 1000, '2 is prime because it has exactly two factors, 1 and itself; 1 has only one.'),
    (v_quiz_id, 38, 'Which blood type is known as the universal donor?', '[{"id": "a", "text": "AB positive"}, {"id": "b", "text": "O negative"}, {"id": "c", "text": "A positive"}, {"id": "d", "text": "B negative"}]'::jsonb, 'b', 25000, 1000, 'O negative red cells carry no A, B or RhD antigens to trigger a reaction.'),
    (v_quiz_id, 39, 'In which city is the United Nations headquartered?', '[{"id": "a", "text": "Geneva"}, {"id": "b", "text": "Vienna"}, {"id": "c", "text": "New York"}, {"id": "d", "text": "Paris"}]'::jsonb, 'c', 20000, 1000, 'The UN headquarters has stood on Manhattan''s East River since 1952.'),
    (v_quiz_id, 40, 'Which metal is liquid at room temperature?', '[{"id": "a", "text": "Lead"}, {"id": "b", "text": "Tin"}, {"id": "c", "text": "Zinc"}, {"id": "d", "text": "Mercury"}]'::jsonb, 'd', 20000, 1000, 'Mercury melts at about minus 39 degrees Celsius, so it stays liquid indoors.'),
    (v_quiz_id, 41, 'Which element is the most abundant in Earth''s crust by mass?', '[{"id": "a", "text": "Oxygen"}, {"id": "b", "text": "Silicon"}, {"id": "c", "text": "Aluminium"}, {"id": "d", "text": "Iron"}]'::jsonb, 'a', 25000, 1000, 'Oxygen makes up roughly 46 percent of the crust by mass, mostly bound in minerals.'),
    (v_quiz_id, 42, 'In which year was the Treaty of Versailles signed?', '[{"id": "a", "text": "1918"}, {"id": "b", "text": "1919"}, {"id": "c", "text": "1920"}, {"id": "d", "text": "1921"}]'::jsonb, 'b', 25000, 1000, 'It was signed on 28 June 1919, formally ending the First World War with Germany.'),
    (v_quiz_id, 43, 'Who wrote the “Aryabhatiya”?', '[{"id": "a", "text": "Brahmagupta"}, {"id": "b", "text": "Bhaskara I"}, {"id": "c", "text": "Aryabhata"}, {"id": "d", "text": "Varahamihira"}]'::jsonb, 'c', 25000, 1000, 'Aryabhata wrote the Aryabhatiya in 499 CE, covering astronomy and mathematics.'),
    (v_quiz_id, 44, 'Which subatomic particle was discovered first?', '[{"id": "a", "text": "Proton"}, {"id": "b", "text": "Neutron"}, {"id": "c", "text": "Neutrino"}, {"id": "d", "text": "Electron"}]'::jsonb, 'd', 25000, 1000, 'J J Thomson identified the electron in 1897, decades before the proton and neutron.'),
    (v_quiz_id, 45, 'What was the name of the lander on India''s Chandrayaan-3 mission?', '[{"id": "a", "text": "Vikram"}, {"id": "b", "text": "Pragyan"}, {"id": "c", "text": "Aryabhata"}, {"id": "d", "text": "Bhaskara"}]'::jsonb, 'a', 25000, 1000, 'Vikram landed near the lunar south pole in August 2023; Pragyan was its rover.'),
    (v_quiz_id, 46, 'Which country spans the most time zones, counting its overseas territories?', '[{"id": "a", "text": "Russia"}, {"id": "b", "text": "France"}, {"id": "c", "text": "United States"}, {"id": "d", "text": "China"}]'::jsonb, 'b', 25000, 1000, 'France reaches twelve time zones through its overseas departments and territories.'),
    (v_quiz_id, 47, 'Which strait separates Asia from North America?', '[{"id": "a", "text": "Strait of Gibraltar"}, {"id": "b", "text": "Strait of Malacca"}, {"id": "c", "text": "Bering Strait"}, {"id": "d", "text": "Strait of Hormuz"}]'::jsonb, 'c', 25000, 1000, 'The Bering Strait runs between Russia''s Chukotka and Alaska.'),
    (v_quiz_id, 48, 'What is the SI unit of electrical resistance?', '[{"id": "a", "text": "Volt"}, {"id": "b", "text": "Ampere"}, {"id": "c", "text": "Watt"}, {"id": "d", "text": "Ohm"}]'::jsonb, 'd', 25000, 1000, 'One ohm is the resistance that passes one ampere under one volt.'),
    (v_quiz_id, 49, 'Which two countries share the longest land border in the world?', '[{"id": "a", "text": "Canada and the United States"}, {"id": "b", "text": "Russia and China"}, {"id": "c", "text": "India and China"}, {"id": "d", "text": "Argentina and Chile"}]'::jsonb, 'a', 25000, 1000, 'Their shared border runs about 8,890 km, including the Alaska section.'),
    (v_quiz_id, 50, 'Which is the only mammal capable of true flight?', '[{"id": "a", "text": "Flying squirrel"}, {"id": "b", "text": "Bat"}, {"id": "c", "text": "Sugar glider"}, {"id": "d", "text": "Colugo"}]'::jsonb, 'b', 20000, 1000, 'Only bats have powered flight; the others glide.');
